#include "stdlib/math/base/special/betaincinv.h"
#include "stdlib/math/base/assert/is_nan.h"

/**
* Returns the excess quantile of a beta prime distribution.
*
* @param p		probability
* @param alpha	first shape parameter
* @param beta	 second shape paramter
* @return		 excess quantile
*
* @example
* double y = stdlib_base_betaprime_quantile( 1.1, 1.0, 1.0 );
* // returns NaN
*/
double stdlib_base_dists_betaprime_quantile( const double p, const double alpha, const double beta ) {
	double x;
	if (
		stdlib_base_is_nan( p ) ||
		stdlib_base_is_nan( alpha ) ||
		stdlib_base_is_nan( beta ) ||
		alpha <= 0.0 ||
		beta <= 4.0 ||
		p < 0.0 ||
		p > 1.0
	) {
		return 0.0 / 0.0; // NaN
	}
	x = stdlib_base_betaincinv( p, alpha, beta );
	return x / ( 1.0-x );
}
